// Deterministic admission simulator. No randomness, no time.
// 30 queued calls per dependency arrive while recommendations is slow
// and holds every permit it can grab.
const demand = { payments: 30, recommendations: 30, search: 30 };

// --- Shared pool: one budget of 50, recommendations grabs first ---
function sharedPool(total) {
  let free = total;
  const admitted = { payments: 0, recommendations: 0, search: 0 };
  // recommendations is slow and arrives first, taking all it can
  for (const dep of ['recommendations', 'payments', 'search']) {
    const take = Math.min(demand[dep], free);
    admitted[dep] = take;
    free -= take;
  }
  return admitted;
}

// --- Bulkhead: per-dependency caps, no shared theft ---
function bulkhead(caps) {
  const admitted = { payments: 0, recommendations: 0, search: 0 };
  for (const dep of ['recommendations', 'payments', 'search']) {
    // TODO 1: admit at most this dependency's own cap (and no more than demand)
    const take = 0;
    admitted[dep] = take;
  }
  return admitted;
}

const shared = sharedPool(50);
// TODO 2: give payments 20, recommendations 10, search 20
const part = bulkhead({ payments: 0, recommendations: 0, search: 0 });

const line = (label, a) => `${label} payments=${a.payments} recommendations=${a.recommendations} search=${a.search}`;
console.log(line('shared', shared));
console.log(line('bulkhead', part));
